"""Generate the six notebooks for this project.

Each notebook starts with a pip install cell, as required, then runs
from the notebooks folder. Charts go to ../charts. Processed tables
are read from ../data/processed when they exist, and notebook 01
rebuilds the clean table from the raw file so the chain is visible.

No em dash character is used anywhere in this file or in the
notebooks it writes. Use commas, periods, and short sentences.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
NB = ROOT / "notebooks"
NB.mkdir(parents=True, exist_ok=True)
PIP = "%pip install -q pandas numpy matplotlib seaborn scikit-learn openpyxl"
SETUP = (
    "import pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\n"
    "from pathlib import Path\n"
    "plt.rcParams['figure.dpi'] = 120\n"
    "ROOT = Path('..').resolve()\nCHARTS = ROOT / 'charts'\nCHARTS.mkdir(exist_ok=True)\n"
    "DATA = ROOT / 'data' / 'processed'\nRAW = ROOT / 'data' / 'raw' / 'online_retail.csv'\n"
    "print('Charts folder:', CHARTS)\nprint('Data folder:', DATA)\n"
)

def nb(cells):
    out = {"cells": [], "metadata": {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"}, "language_info": {"name": "python", "version": "3.12"}}, "nbformat": 4, "nbformat_minor": 5}
    for kind, source in cells:
        out["cells"].append({"cell_type": kind, "metadata": {}, "source": source.splitlines(True) if kind == "code" else source, "outputs": [], "execution_count": None} if kind == "code" else {"cell_type": "markdown", "metadata": {}, "source": source})
    return out

def md(text):
    return ("markdown", text)

def code(text):
    return ("code", text)

def save(name, cells):
    path = NB / name
    path.write_text(json.dumps(nb(cells), indent=1), encoding="utf-8")
    print("Wrote", path)

# Notebook 01
save("01_load_and_clean.ipynb", [
    code(PIP),
    md("# 01. Load and clean the data\n\n## What this notebook does, in plain words\n\nA shop sells things. Each row in the raw file is one line on one receipt. This notebook loads those lines, counts what is messy, and cleans the file step by step. Cleaning matters because messy rows can quietly change every later answer.\n\n## The dataset, stated plainly\n\nThe source is the UCI Machine Learning Repository, Online Retail II, dataset 502, by Daqing Chen (2012). It covers a UK based online retailer that mainly sells unique gift ware, and many of its customers are wholesalers. The full UCI file covers 1 December 2009 to 9 December 2011 and has 1,067,371 rows. This build uses the December 2010 to December 2011 slice, served as a CSV mirror, with 541,909 rows. That slice is the part most public RFM tutorials use. The difference is stated here so no one mistakes this slice for the full file.\n\n## Cleaning rules, in order\n\n1. Drop cancelled invoices. A cancelled invoice number starts with the letter C.\n2. Drop rows with quantity at or below zero, or unit price at or below zero.\n3. Drop rows with no CustomerID. Customer analysis needs a customer.\n4. Add Revenue for each line: Quantity times UnitPrice, in pounds sterling.\n\n## What to watch for\n\nRows with no CustomerID are a large group, not a small typo. They are counted below, not hidden. December 2011 is a partial month, because the data stop on 9 December 2011. Later notebooks flag that month instead of treating it as a full month."),
    code(SETUP),
    code("df = pd.read_csv(RAW, encoding='utf-8')\nprint('Raw shape:', df.shape)\nprint(df.dtypes)\nprint(df.head(3).to_string())\nprint('Date range in raw text:', df['InvoiceDate'].min(), 'to', df['InvoiceDate'].max())\nprint('Countries in raw file:', df['Country'].nunique())\nprint('Missing values per column:')\nprint(df.isna().sum().to_string())"),
    code("missing = df.isna().sum()\nfig, ax = plt.subplots(figsize=(9, 4))\nmissing.plot(kind='bar', ax=ax, color='#2a7f62')\nax.set_title('Missing values per column in the raw file')\nax.set_ylabel('Rows with a missing value')\nplt.xticks(rotation=30, ha='right')\nplt.tight_layout()\nplt.savefig(CHARTS / '01_missing_values.png')\nplt.show()\nprint('Largest gap: CustomerID is missing in', int(missing['CustomerID']), 'raw rows.')"),
    code("n_raw = len(df)\ncancelled = int(df['InvoiceNo'].astype(str).str.startswith('C').sum())\nd = df[~df['InvoiceNo'].astype(str).str.startswith('C')].copy()\nd = d[(d['Quantity'] > 0) & (d['UnitPrice'] > 0)]\nmissing_after = int(d['CustomerID'].isna().sum())\nd = d.dropna(subset=['CustomerID']).copy()\nd['InvoiceDate'] = pd.to_datetime(d['InvoiceDate'])\nd['Revenue'] = d['Quantity'] * d['UnitPrice']\nprint('Raw rows:', n_raw)\nprint('Cancelled rows removed:', cancelled)\nprint('Missing CustomerID rows removed at the customer step:', missing_after)\nprint('Clean rows kept:', len(d))\nprint('Clean revenue, pounds:', round(d['Revenue'].sum(), 2))\nprint('Clean customers:', d['CustomerID'].nunique())\nprint('Clean invoices:', d['InvoiceNo'].nunique())\nprint('Clean date range:', d['InvoiceDate'].min(), 'to', d['InvoiceDate'].max())\nd.to_csv(DATA / 'clean_transactions.csv', index=False)"),
    code("labels = ['Raw rows', 'After removing\\ncancellations and\\nbad prices', 'Clean rows\\n(customer known)']\nvals = [n_raw, n_raw - cancelled, len(d)]\nfig, ax = plt.subplots(figsize=(9, 4))\nax.bar(labels, vals, color=['#888888', '#4a90a4', '#2a7f62'])\nax.set_title('How many rows survive each cleaning step')\nax.set_ylabel('Rows')\nfor x, v in enumerate(vals):\n    ax.text(x, v + 8000, f'{v:,}', ha='center')\nplt.tight_layout()\nplt.savefig(CHARTS / '02_cleaning_funnel.png')\nplt.show()"),
    md("## What we learned\n\nThe clean file has 397,884 rows, 4,338 customers, and 18,532 invoices, with revenue of 8,911,407.90 pounds. The biggest loss is rows with no customer, which is normal for this public file, because guest or manual lines carry no CustomerID. Those rows cannot be used for customer segments, so they are left out of RFM work, and that limit is stated again in notebook 04.\n\nNext: notebook 02 looks at sales over time."),
])

# Notebook 02
save("02_sales_trends.ipynb", [
    code(PIP),
    md("# 02. Sales trends over time\n\n## What this notebook does, in plain words\n\nA trend is a pattern over time. This notebook groups the clean sales by month, by weekday, and by hour of day, so we can see when the shop is busy and when it is quiet.\n\n## One warning before the charts\n\nDecember 2011 is a partial month. The data stop on 9 December 2011, so its bar looks low for a simple reason: most of the month is missing. Do not read it as a collapse in demand. Complete months run from December 2010 to November 2011."),
    code(SETUP),
    code("df = pd.read_csv(DATA / 'clean_transactions.csv', parse_dates=['InvoiceDate'])\nprint('Rows:', len(df), 'Revenue, pounds:', round(df['Revenue'].sum(), 2))\nmonthly = df.groupby(df['InvoiceDate'].dt.to_period('M')).agg(revenue=('Revenue', 'sum'), orders=('InvoiceNo', 'nunique'), customers=('CustomerID', 'nunique')).reset_index()\nmonthly['month'] = monthly['InvoiceDate'].astype(str)\nprint(monthly.to_string(index=False))"),
    code("fig, ax = plt.subplots(figsize=(10, 5))\nax.bar(monthly['month'], monthly['revenue'], color='#2a7f62')\nax.set_title('Monthly revenue, December 2010 to December 2011 (December 2011 is partial)')\nax.set_ylabel('Revenue, pounds')\nplt.xticks(rotation=45, ha='right')\nplt.tight_layout()\nplt.savefig(CHARTS / '03_monthly_revenue.png')\nplt.show()\ncomplete = monthly[monthly['month'] != '2011-12']\nprint('Best complete month:', complete.loc[complete['revenue'].idxmax(), 'month'], round(complete['revenue'].max(), 2))\nprint('Quietest complete month:', complete.loc[complete['revenue'].idxmin(), 'month'], round(complete['revenue'].min(), 2))\nprint('Average complete month, pounds:', round(complete['revenue'].mean(), 2))"),
    code("fig, ax = plt.subplots(figsize=(10, 4))\nax.plot(monthly['month'], monthly['orders'], marker='o', color='#4a90a4')\nax.set_title('Monthly orders')\nax.set_ylabel('Distinct invoices')\nplt.xticks(rotation=45, ha='right')\nplt.tight_layout()\nplt.savefig(CHARTS / '04_monthly_orders.png')\nplt.show()"),
    code("df['weekday'] = df['InvoiceDate'].dt.day_name()\norder = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']\nwd = df.groupby('weekday')['Revenue'].sum().reindex(order)\nfig, ax = plt.subplots(figsize=(9, 4))\nwd.plot(kind='bar', ax=ax, color='#4a90a4')\nax.set_title('Revenue by weekday')\nax.set_ylabel('Revenue, pounds')\nplt.tight_layout()\nplt.savefig(CHARTS / '05_weekday_revenue.png')\nplt.show()\nprint(wd.to_string())"),
    code("df['hour'] = df['InvoiceDate'].dt.hour\nhr = df.groupby('hour')['Revenue'].sum()\nfig, ax = plt.subplots(figsize=(9, 4))\nhr.plot(kind='bar', ax=ax, color='#2a7f62')\nax.set_title('Revenue by hour of day')\nax.set_ylabel('Revenue, pounds')\nax.set_xlabel('Hour (24 hour clock)')\nplt.tight_layout()\nplt.savefig(CHARTS / '06_hour_revenue.png')\nplt.show()\nprint('Busiest hour:', hr.idxmax(), 'with', round(hr.max(), 2), 'pounds.')"),
    md("## What we learned\n\nNovember 2011 is the best complete month, at 1,161,817.38 pounds, followed by October 2011 at 1,039,318.79 pounds. February 2011 is the quietest complete month, at 447,137.35 pounds. That autumn rise fits a gift shop heading into the holiday season, but this data alone cannot prove the cause. It shows timing, not motive. The weekday chart shows Thursday as the strongest day, and midday as the busiest time, which is useful for staffing and for timing a message, not a promise of future sales.\n\nNext: notebook 03 looks at which countries and products drive the money."),
])

# Notebook 03
